import subprocess
import shutil

openvela = os.path.expanduser("~/openvela")
nuttx = os.path.join(openvela, "nuttx")
prebuilts = os.path.join(openvela, "prebuilts/build-tools/linux-x86_64/bin")

# Step 1: Create ROMFS data directory
romfs_dir = os.path.join(nuttx, "romfs_data")
if os.path.exists(romfs_dir):
    shutil.rmtree(romfs_dir)
os.makedirs(romfs_dir)

# Step 2: Copy weight file
weight_src = os.path.join(openvela, "contest2026_141_QiDiAi/app/jianmu/v9v3_weights.baize")
shutil.copy2(weight_src, os.path.join(romfs_dir, "v9v3_weights.baize"))
print(f"Copied weight file ({os.path.getsize(weight_src)} bytes)")

# Step 3: Create ROMFS image using genromfs
genromfs = os.path.join(prebuilts, "genromfs")
romfs_img = os.path.join(nuttx, "data.romfs")

result = subprocess.run(
    [genromfs, "-f", romfs_img, "-d", romfs_dir, "-V", "DATA"],
    capture_output=True, text=True, timeout=30
)
print(f"genromfs: rc={result.returncode}")
if result.returncode != 0:
    print(f"Error: {result.stderr}")
    exit(1)

romfs_size = os.path.getsize(romfs_img)
print(f"ROMFS image: {romfs_size} bytes ({romfs_size/1024/1024:.1f} MB)")

# Step 4: Convert to C array
romfs_h = os.path.join(nuttx, "boards/arm/qemu/contest2026_141_board/src/romfs_data.h")
with open(romfs_img, "rb") as f:
    data = f.read()

with open(romfs_h, "w") as f:
    f.write(f"/* Auto-generated ROMFS image - {len(data)} bytes */\n")
    f.write(f"static const unsigned char romfs_data[] = {{\n")
    for i in range(0, len(data), 16):
        chunk = data[i:i+16]
        hex_str = ",".join(f"0x{b:02x}" for b in chunk)
        f.write(f"  {hex_str},\n")
    f.write(f"}};\n")
    f.write(f"static const unsigned int romfs_data_len = {len(data)};\n")

h_size = os.path.getsize(romfs_h)
print(f"Generated {romfs_h} ({h_size/1024/1024:.1f} MB)")

# Step 5: Update board_appinit.c to mount ROMFS at /data
appinit = os.path.join(openvela, "vendor/openvela/boards/contest2026_141_board/src/board_appinit.c")
with open(appinit, "w") as f:
    f.write("""#include <nuttx/config.h>
#include <nuttx/board.h>
#include <sys/mount.h>
#include <stdio.h>
#include <errno.h>

#include "romfs_data.h"

int board_app_initialize(uintptr_t arg)
{
  int ret;

  /* Mount ROMFS at /data containing v9v3 weights */
  ret = mount(NULL, "/data", "romfs", MS_RDONLY, romfs_data);
  if (ret < 0)
    {
      printf("board_appinit: mount /data failed: %d\\n", errno);
    }
  else
    {
      printf("board_appinit: /data mounted (ROMFS, %u bytes)\\n", romfs_data_len);
    }

  return 0;
}
""")
print(f"Updated board_appinit.c")

print("\nDone! Now rebuild with build_jianmu_full.py")
