 * v10.c - BaizeEmbeddingV10 C Engine Implementation
 *
 * Pure Source Pool architecture - all operations are simple matrix ops.
 * Only depends on libc + libm (no BLAS, no external libs).
 */
#include "v10.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ---- Weight file format ---- */
#define BAIZE_MAGIC "BAIZE"
#define BAIZE_VERSION_V10 2

typedef struct {
    char name[52];
    uint32_t offset;
    uint32_t size;
} tensor_entry_t;

/* ---- Per-layer weights ---- */
typedef struct {
    const float *write_gate_w;    /* [24, 384] */
    const float *write_gate_b;    /* [24] */
    const float *fast_read_w;     /* [384, 24] */
    const float *fast_read_b;     /* [384] */
    const float *medium_read_w;   /* [384, 24] */
    const float *medium_read_b;   /* [384] */
    const float *slow_read_w;     /* [384, 24] */
    const float *slow_read_b;     /* [384] */
    const float *fusion_gate_w;   /* [3, 1152] */
    const float *fusion_gate_b;   /* [3] */
} pool_layer_t;

/* ---- Model structure ---- */
struct v10_model {
    const float *embedding;       /* [4096, 384] */
    const float *skip_gates;      /* [6] */
    pool_layer_t layers[V10_NUM_LAYERS];
    const float *bottleneck_w;    /* [72, 384] */
    const float *bottleneck_b;    /* [72] */
    const float *output_proj_w;   /* [1024, 72] */
    const float *output_proj_b;   /* [1024] */
    const float *output_norm_w;   /* [1024] */
    const float *output_norm_b;   /* [1024] */
    void *raw_buf;                /* raw malloc'd buffer for all weights */
};

/* Global model instance */
static v10_model_t *g_model = NULL;

/* ---- Helper: find tensor by name suffix ---- */
static const float *find_tensor(const uint8_t *base, const tensor_entry_t *entries,
                                 int n, const char *suffix)
{
    for (int i = 0; i < n; i++) {
        if (strstr(entries[i].name, suffix)) {
            return (const float *)(base + entries[i].offset);
        }
    }
    return NULL;
}

/* ---- Load model ---- */
int v10_init(const char *weight_path)
{
    FILE *f = fopen(weight_path, "rb");
    if (!f) {
        fprintf(stderr, "v10_init: cannot open %s\n", weight_path);
        return -1;
    }

    /* Read header */
    char magic[6] = {0};
    uint32_t version, num_tensors;
    if (fread(magic, 1, 5, f) != 5 ||
        fread(&version, 4, 1, f) != 1 ||
        fread(&num_tensors, 4, 1, f) != 1) {
        fprintf(stderr, "v10_init: bad header\n");
        fclose(f);
        return -1;
    }

    if (memcmp(magic, BAIZE_MAGIC, 5) != 0 || version != BAIZE_VERSION_V10) {
        fprintf(stderr, "v10_init: bad magic/version: %s v%d\n", magic, version);
        fclose(f);
        return -1;
    }

    /* Read tensor table */
    tensor_entry_t *entries = (tensor_entry_t *)malloc(num_tensors * sizeof(tensor_entry_t));
    if (!entries) { fclose(f); return -1; }

    for (uint32_t i = 0; i < num_tensors; i++) {
        if (fread(entries[i].name, 1, 52, f) != 52 ||
            fread(&entries[i].offset, 4, 1, f) != 1 ||
            fread(&entries[i].size, 4, 1, f) != 1) {
            fprintf(stderr, "v10_init: bad tensor table\n");
            free(entries);
            fclose(f);
            return -1;
        }
    }

    /* Find file size and read all data */
    fseek(f, 0, SEEK_END);
    long file_size = ftell(f);
    uint8_t *buf = (uint8_t *)malloc(file_size);
    if (!buf) { free(entries); fclose(f); return -1; }

    fseek(f, 0, SEEK_SET);
    if ((long)fread(buf, 1, file_size, f) != file_size) {
        fprintf(stderr, "v10_init: short read\n");
        free(buf);
        free(entries);
        fclose(f);
        return -1;
    }
    fclose(f);

    /* Allocate and populate model */
    v10_model_t *m = (v10_model_t *)calloc(1, sizeof(v10_model_t));
    if (!m) { free(buf); free(entries); return -1; }

