 * QiDiAi Jianmu - on-device semantic indexing demo (openvela)
 * Uses V10 engine (Pure Source Pool) - 1.93M params, 7.3MB, fast
 */
#include <stdio.h>
#include "v10.h"
#include "semantic_index.h"

#ifndef V10_MODEL_PATH
#define V10_MODEL_PATH "/data/v10_weights.baize"
#endif

static const char *k_corpus[] =
{
  "上次聊装修的朋友 小王 微信",
  "周五的团队周会纪要 关于 openvela 移植",
  "妈妈生日提醒 下周二 买蛋糕",
  "健身计划 每周三跑步五公里",
  "装修预算表格 水电改造两万元",
  "围棋课报名 周末上午",
};

int main(int argc, char *argv[])
{
  const char *model_path = (argc > 1) ? argv[1] : V10_MODEL_PATH;

  printf("=== QiDiAi Jianmu (V10 Pure Source Pool) ===\n");

  if (v10_init(model_path) != 0)
    {
      fprintf(stderr, "Jianmu: V10 model load failed (%s)\n", model_path);
      return 1;
    }
  printf("V10 engine ready, dim = %d\n", v10_dim());

  semantic_index_t idx;
  si_build(&idx, k_corpus, sizeof(k_corpus) / sizeof(k_corpus[0]));
  printf("Indexed %d documents (fully offline).\n", idx.count);

  const char *queries[] =
  {
    "找上次聊装修的朋友",
    "生日蛋糕",
    "运动健身",
  };
  int n_queries = sizeof(queries) / sizeof(queries[0]);

  for (int q = 0; q < n_queries; q++)
    {
      printf("\nQuery: \"%s\"\n", queries[q]);
      int results[3];
      float scores[3];
      int n = si_search(&idx, queries[q], results, scores);
      for (int i = 0; i < n; i++)
        {
          printf("  Top-%d: %.4f  %s\n", i + 1, scores[i], idx.docs[results[i]].text);
        }
    }

  si_free(&idx);
  v10_free();
  printf("\n=== Jianmu demo complete ===\n");
  return 0;
}
